-- TORVO V2 FINAL DEALER ORDER DEVICE BOUNDARY
-- Install after dealer auth, sales-order integrity and additional purchase order migrations.

drop function if exists dealer_confirm_sales_order_revision(uuid,integer);
drop function if exists request_additional_purchase_order(uuid,jsonb,text);
drop function if exists get_dealer_order_history_30d();

create or replace function dealer_confirm_sales_order_revision(p_sales_order uuid,p_revision integer,p_device_id text,p_session_token text) returns void language plpgsql security definer set search_path=public as $$declare a app_users%rowtype;did uuid;d sales_documents%rowtype;begin did:=dealer_assert_my_device_session(p_device_id,p_session_token);select * into a from app_users where auth_user_id=auth.uid() and active=true and role='dealer';select * into d from sales_documents where id=p_sales_order and doc_type='sales_order' and dealer_id=did for update;if not found then raise exception 'SALES ORDER NOT FOUND';end if;if d.estimate_created_at is not null or d.locked_at is not null then raise exception 'ORDER ALREADY LOCKED';end if;if p_revision is null or p_revision<>d.revision_no then raise exception 'ONLY LATEST EXACT REVISION CAN BE CONFIRMED';end if;update sales_documents set dealer_ok_revision=d.revision_no,dealer_ok_at=now(),status='dealer_ok' where id=d.id;insert into audit_log(actor_id,action,entity_type,entity_id,details)values(a.id,'DEALER_OK','sales_order',d.id::text,jsonb_build_object('revision_no',d.revision_no));end$$;

create or replace function request_additional_purchase_order(p_original_sales_order uuid,p_lines jsonb,p_reason text,p_device_id text,p_session_token text) returns uuid language plpgsql security definer set search_path=public as $$declare a app_users%rowtype;did uuid;orig sales_documents%rowtype;rg text;add_order uuid;link_id uuid;ln jsonb;iid uuid;q numeric;r numeric;sub numeric:=0;begin did:=dealer_assert_my_device_session(p_device_id,p_session_token);select * into a from app_users where auth_user_id=auth.uid() and active=true and role='dealer';select * into orig from sales_documents where id=p_original_sales_order and doc_type='sales_order' and dealer_id=did;if not found then raise exception 'ORIGINAL SALES ORDER NOT FOUND';end if;if orig.estimate_created_at is null then raise exception 'ADD MORE ITEMS IS AVAILABLE AFTER ORIGINAL ESTIMATE CREATION';end if;if jsonb_typeof(p_lines)<>'array' or jsonb_array_length(p_lines)=0 then raise exception 'ADDITIONAL ORDER LINES REQUIRED';end if;if exists(select 1 from(select x->>'item_id' item_id,count(*) c from jsonb_array_elements(p_lines)x group by x->>'item_id')s where s.item_id is null or s.c>1)then raise exception 'DUPLICATE OR MISSING ITEM IN ADDITIONAL ORDER';end if;select rate_group into rg from dealers where id=did and status='approved';if rg is null then raise exception 'APPROVED DEALER RATE GROUP REQUIRED';end if;insert into sales_documents(dealer_id,doc_type,status,parent_id,root_order_id,subtotal,final_payable,created_by,revision_no,dealer_modification_limit,dealer_modifications_used)values(did,'sales_order','additional_pending_approval',orig.id,coalesce(orig.root_order_id,orig.id),0,0,a.id,1,2,0)returning id into add_order;for ln in select * from jsonb_array_elements(p_lines)loop begin iid:=(ln->>'item_id')::uuid;q:=(ln->>'qty')::numeric;exception when others then raise exception 'INVALID ADDITIONAL ORDER LINE';end;if q is null or q<=0 or q<>trunc(q) or q>9999 then raise exception 'QUANTITY MUST BE INTEGER 1 TO 9999';end if;perform 1 from catalog_items where id=iid and active=true;if not found then raise exception 'ITEM UNAVAILABLE';end if;select selling_rate into r from item_rates where item_id=iid and rate_group=rg and min_qty<=q order by min_qty desc limit 1;if r is null then raise exception 'RATE UNAVAILABLE FOR AN ITEM';end if;insert into sales_document_lines(document_id,item_id,qty,rate,amount)values(add_order,iid,q,r,round(q*r,2));sub:=sub+round(q*r,2);end loop;update sales_documents set subtotal=sub,final_payable=sub where id=add_order;insert into additional_purchase_order_links(original_sales_order_id,original_estimate_id,additional_sales_order_id,dealer_id,requested_by,request_reason)values(orig.id,(select id from sales_documents where parent_id=orig.id and doc_type='estimate' order by created_at desc limit 1),add_order,did,a.id,nullif(upper(trim(p_reason)),''))returning id into link_id;insert into sales_order_revisions(sales_order_id,revision_no,changed_by,actor_role,change_reason,after_data)values(add_order,1,a.id,'dealer','ADDITIONAL PURCHASE ORDER REQUESTED',jsonb_build_object('original_sales_order_id',orig.id,'subtotal',sub,'lines',p_lines));insert into audit_log(actor_id,action,entity_type,entity_id,details)values(a.id,'ADDITIONAL_PURCHASE_ORDER_REQUESTED','sales_order',add_order::text,jsonb_build_object('original_sales_order_id',orig.id,'link_id',link_id,'subtotal',sub));return add_order;end$$;

create or replace function get_dealer_order_history_30d(p_device_id text,p_session_token text) returns table(document_id uuid,document_type text,document_status text,revision_no integer,subtotal numeric,freight numeric,other_charges numeric,final_payable numeric,created_at timestamptz,parent_id uuid,root_order_id uuid) language plpgsql security definer set search_path=public as $$declare did uuid;begin did:=dealer_assert_my_device_session(p_device_id,p_session_token);return query select d.id,d.doc_type,d.status,d.revision_no,d.subtotal,d.freight,d.other_charges,d.final_payable,d.created_at,d.parent_id,d.root_order_id from sales_documents d where d.dealer_id=did and d.doc_type in('sales_order','estimate') and d.created_at>=now()-interval '30 days' order by d.created_at desc;end$$;

revoke all on function dealer_confirm_sales_order_revision(uuid,integer,text,text),request_additional_purchase_order(uuid,jsonb,text,text,text),get_dealer_order_history_30d(text,text) from public,anon;
grant execute on function dealer_confirm_sales_order_revision(uuid,integer,text,text),request_additional_purchase_order(uuid,jsonb,text,text,text),get_dealer_order_history_30d(text,text) to authenticated;
